cat > tests/LocaleController.test.ts <<'EOF'
import { beforeAll, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'

describe('POST /locale', () => {
  let http: TestApp

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  it('rejects unsupported locales', async () => {
    await http.post('/locale', { locale: 'fr' }).assertStatus(422)
    await http.post('/locale', {}).assertStatus(422)
  })

  it('sets the locale cookie and redirects to the referer', async () => {
    const res = await http.post('/locale', { locale: 'ja' }, { headers: { Referer: 'http://localhost/posts?page=2' } })
    const raw = (res as any).response ?? res
    expect(raw.headers.get('location')).toBe('/posts?page=2')
    expect(raw.headers.get('set-cookie')).toContain('locale=ja')
  })
})
EOF
